<template>
  <div class="weather-container" v-click-outside="closeDropdown">

    <div class="city-wrap">
      <div class="city-btn" @click="dropdownOpen = !dropdownOpen" :class="{ 'city-btn--open': dropdownOpen }">
        <v-icon size="14" color="#6366f1">mdi-map-marker</v-icon>
        <span class="city-name">{{ currentCityLabel }}</span>
        <v-icon size="14" color="#94a3b8" class="city-chevron">mdi-chevron-down</v-icon>
      </div>
      <transition name="dropdown">
        <div class="city-dropdown" v-if="dropdownOpen">
          <div class="city-dropdown-inner">
            <div v-for="city in localizedCities" :key="city.q"
                 class="city-option" :class="{ 'city-option--active': city.q === selectedCity }"
                 @click="selectCity(city)">
              <v-icon size="12" color="#6366f1" v-if="city.q === selectedCity">mdi-check</v-icon>
              <span>{{ city.label }}</span>
            </div>
          </div>
        </div>
      </transition>
    </div>

    <div class="weather">
      <img v-if="weatherImg" class="weather-icon" :src="weatherImg" alt="" />
      <span class="weather-temp" :style="{ color: weatherTempColor || '#1e293b' }">{{ weatherTemp }}</span>
    </div>

    <div class="sep"></div>

    <div class="curr-wrap" v-click-outside="closeCurrDropdown">
      <div class="curr-btn" @click="currDropdownOpen = !currDropdownOpen" :class="{ 'curr-btn--open': currDropdownOpen }">
        <span class="curr-symbol">{{ selectedCurrency.symbol }}</span>
        <span class="curr-val" :class="{ 'is-error': currencyIsUnload }">{{ currencyInfo }}</span>
        <span class="currency-nbu">НБУ</span>
        <v-icon size="14" color="#94a3b8" class="curr-chevron">mdi-chevron-down</v-icon>
      </div>
      <transition name="dropdown">
        <div class="city-dropdown" v-if="currDropdownOpen" style="left:auto;right:0;">
          <div class="city-dropdown-inner">
            <div v-for="curr in localizedCurrencies" :key="curr.code"
                 class="city-option" :class="{ 'city-option--active': curr.code === selectedCurrencyCode }"
                 @click="selectCurrency(curr)">
              <v-icon size="12" color="#6366f1" v-if="curr.code === selectedCurrencyCode">mdi-check</v-icon>
              <span class="curr-option-symbol">{{ curr.symbol }}</span>
              <span>{{ curr.label }}</span>
            </div>
          </div>
        </div>
      </transition>
    </div>

  </div>
</template>

<script>
const CITIES_CONFIG = [
  { key: 'kyiv',           q: 'Kyiv'            },
  { key: 'kharkiv',        q: 'Kharkiv'         },
  { key: 'odessa',         q: 'Odessa'          },
  { key: 'dnipro',         q: 'Dnipro'          },
  { key: 'zaporizhzhia',   q: 'Zaporizhzhia'    },
  { key: 'lviv',           q: 'Lviv'            },
  { key: 'kryvyiRih',      q: 'Kryvyi Rih'      },
  { key: 'mykolaiv',       q: 'Mykolaiv'        },
  { key: 'mariupol',       q: 'Mariupol'        },
  { key: 'luhansk',        q: 'Luhansk'         },
  { key: 'vinnytsia',      q: 'Vinnytsia'       },
  { key: 'kherson',        q: 'Kherson'         },
  { key: 'poltava',        q: 'Poltava'         },
  { key: 'chernihiv',      q: 'Chernihiv'       },
  { key: 'cherkasy',       q: 'Cherkasy'        },
  { key: 'sumy',           q: 'Sumy'            },
  { key: 'zhytomyr',       q: 'Zhytomyr'        },
  { key: 'rivne',          q: 'Rivne'           },
  { key: 'ivanoFrankivsk', q: 'Ivano-Frankivsk' },
  { key: 'ternopil',       q: 'Ternopil'        },
  { key: 'khmelnytskyi',   q: 'Khmelnytskyi'    },
  { key: 'uzhhorod',       q: 'Uzhhorod'        },
  { key: 'chernivtsi',     q: 'Chernivtsi'      },
  { key: 'lutsk',          q: 'Lutsk'           },
  { key: 'kropyvnytskyi',  q: 'Kropyvnytskyi'   },
]

const CURRENCIES_CONFIG = [
  { code: 'USD', symbol: '$', txt: 'Долар США',        labelKey: 'weather.dollar' },
  { code: 'EUR', symbol: '€', txt: 'Євро',             labelKey: 'weather.euro'   },
  { code: 'CNY', symbol: '¥', txt: 'Юань Женьміньбі', labelKey: 'weather.yuan'   },
]

export default {
  name: 'WeatherComponent',

  directives: {
    'click-outside': {
      mounted(el, binding) {
        el._clickOutside = (e) => { if (!el.contains(e.target)) binding.value() }
        document.addEventListener('click', el._clickOutside)
      },
      unmounted(el) {
        document.removeEventListener('click', el._clickOutside)
      },
    },
  },

  data() {
    return {
      selectedCity:         'Kyiv',
      dropdownOpen:         false,
      selectedCurrencyCode: 'USD',
      currDropdownOpen:     false,
      weatherTemp:          '',
      weatherImg:           '',
      weatherTempColor:     '',
      currencyInfo:         '',
      weatherIsUnload:      false,
      currencyIsUnload:     false,
      weatherInterval:      null,
    }
  },

  computed: {
    localizedCities() {
      return CITIES_CONFIG.map(c => ({ q: c.q, label: this.$t(`weather.cities.${c.key}`) }))
    },
    localizedCurrencies() {
      return CURRENCIES_CONFIG.map(c => ({ ...c, label: this.$t(c.labelKey) }))
    },
    selectedCurrency() {
      return this.localizedCurrencies.find(c => c.code === this.selectedCurrencyCode)
          || this.localizedCurrencies[0]
    },
    currentCityLabel() {
      return this.localizedCities.find(c => c.q === this.selectedCity)?.label || '—'
    },
  },

  mounted() {
    this.showWeather(this.selectedCity)
    this.showCurrency()
    this.weatherInterval = setInterval(() => {
      this.showWeather(this.selectedCity)
      this.showCurrency()
    }, 1_800_000)
  },

  beforeUnmount() {
    if (this.weatherInterval) clearInterval(this.weatherInterval)
  },

  methods: {
    selectCity(city) {
      this.selectedCity = city.q
      this.dropdownOpen = false
      this.showWeather(city.q)
    },
    closeDropdown()     { this.dropdownOpen     = false },
    closeCurrDropdown() { this.currDropdownOpen = false },
    selectCurrency(curr) {
      this.selectedCurrencyCode = curr.code
      this.currDropdownOpen     = false
      this.showCurrency()
    },

    async showWeather(location) {
      try {
        const res  = await fetch(`https://api.weatherapi.com/v1/current.json?key=5f6ae58e18e644888bf182855242904&q=${location}`)
        const data = await res.json()
        const temp = data.current.temp_c
        this.weatherTemp     = `${temp}°C`
        this.weatherImg      = data.current.condition.icon
        this.weatherIsUnload = false
        if (parseFloat(temp) >= 35)    this.weatherTempColor = '#f97316'
        else if (parseFloat(temp) < 0) this.weatherTempColor = '#3b82f6'
        else                           this.weatherTempColor = '#1e293b'
      } catch {
        this.weatherIsUnload = true
      }
    },

    async showCurrency() {
      try {
        const res  = await fetch('https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?json')
        const data = await res.json()
        const curr = data.find(f => f.txt === this.selectedCurrency.txt)
        this.currencyInfo     = curr ? curr.rate : '—'
        this.currencyIsUnload = false
      } catch {
        this.currencyIsUnload = true
        this.currencyInfo     = this.$t('weather.error')
      }
    },
  },
}
</script>

<style scoped>
.weather-container { display: flex; align-items: center; gap: 14px; position: relative; }
.city-wrap { position: relative; }
.city-btn { display: flex; align-items: center; gap: 5px; padding: 6px 10px; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 20px; cursor: pointer; transition: all 0.2s ease; user-select: none; &:hover, &--open { border-color: #6366f1; background: #fff; box-shadow: 0 2px 10px rgba(99,102,241,0.12); } }
.city-name { font-size: 12px; font-weight: 700; color: #475569; white-space: nowrap; }
.city-chevron { transition: transform 0.2s ease; .city-btn--open & { transform: rotate(180deg); } }
.city-dropdown { position: absolute; top: calc(100% + 8px); left: 0; background: #fff; border-radius: 14px; border: 1px solid #e2e8f0; box-shadow: 0 8px 28px rgba(0,0,0,0.12); z-index: 1000; overflow: hidden; min-width: 180px; }
.city-dropdown-inner { max-height: 280px; overflow-y: auto; padding: 6px; scrollbar-width: thin; scrollbar-color: #e2e8f0 transparent; &::-webkit-scrollbar { width: 4px; } &::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 2px; } }
.city-option { display: flex; align-items: center; gap: 8px; padding: 8px 12px; font-size: 13px; font-weight: 500; color: #475569; cursor: pointer; border-radius: 8px; transition: all 0.15s; &:hover { background: #f8fafc; color: #1e293b; } &--active { background: rgba(99,102,241,.06); color: #6366f1; font-weight: 700; } }
.dropdown-enter-active { animation: dd-in 0.15s ease; }
.dropdown-leave-active { animation: dd-in 0.1s ease reverse; }
@keyframes dd-in { from { opacity: 0; transform: translateY(-6px) scale(0.97); } to { opacity: 1; transform: translateY(0) scale(1); } }
.weather { display: flex; align-items: center; gap: 6px; }
.weather-icon { width: 28px; height: 28px; object-fit: contain; }
.weather-temp { font-size: 15px; font-weight: 700; letter-spacing: -0.3px; white-space: nowrap; }
.sep { width: 1px; height: 18px; background: #e2e8f0; flex-shrink: 0; }
.curr-wrap { position: relative; }
.curr-btn { display: flex; align-items: center; gap: 4px; cursor: pointer; position: relative; padding: 2px 20px 2px 0; &--open .curr-chevron, &:hover .curr-chevron { color: #6366f1 !important; } }
.curr-symbol { font-size: 15px; font-weight: 800; color: #16a34a; }
.curr-val { font-size: 15px; font-weight: 700; color: #16a34a; letter-spacing: -0.3px; white-space: nowrap; &.is-error { color: #ef4444; } }
.curr-chevron { position: absolute; right: 0; top: 50%; transform: translateY(-50%); transition: transform 0.2s ease; .curr-btn--open & { transform: translateY(-50%) rotate(180deg); } }
.curr-option-symbol { font-size: 13px; font-weight: 700; color: #6366f1; width: 16px; text-align: center; }
.currency-nbu { font-size: 9px; font-weight: 700; color: #94a3b8; letter-spacing: 1px; position: absolute; top: -8px; right: -24px; }
</style>
